def mean(v):
    return sum(v) / len(v)

def cov(x, y):
    mx, my = mean(x), mean(y)
    return sum((a - mx) * (b - my) for a, b in zip(x, y)) / len(x)

def corr(x, y):
    return cov(x, y) / (cov(x, x) ** 0.5 * cov(y, y) ** 0.5)

x = [1, 2, 3, 4, 5]
y = [2, 3, 5, 6, 9]
print(round(cov(x, y), 2))   # 3.4

